-- Transit stop catalog extracted from database/stops.json
CREATE TABLE IF NOT EXISTS transit_routes (
  route_code VARCHAR(20) PRIMARY KEY,
  is_loop TINYINT(1) NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS transport_stops (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  stop_name VARCHAR(200) NOT NULL,
  latitude DECIMAL(10,7) NOT NULL,
  longitude DECIMAL(10,7) NOT NULL,
  UNIQUE KEY uk_transport_stops_name_point (stop_name, latitude, longitude),
  INDEX idx_transport_stops_name (stop_name),
  INDEX idx_transport_stops_location (latitude, longitude)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS route_stop_services (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  stop_id INT UNSIGNED NOT NULL,
  route_code VARCHAR(20) NOT NULL,
  is_departure_hub TINYINT(1) NOT NULL DEFAULT 0,
  CONSTRAINT fk_route_stop_services_stop FOREIGN KEY (stop_id) REFERENCES transport_stops(id) ON DELETE CASCADE,
  INDEX idx_route_stop_services_stop (stop_id),
  INDEX idx_route_stop_services_route (route_code),
  UNIQUE KEY uk_route_stop_services_stop_route (stop_id, route_code)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS route_stop_labels (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  route_code VARCHAR(20) NOT NULL,
  stop_name VARCHAR(200) NOT NULL,
  vertex_index INT UNSIGNED NOT NULL,
  UNIQUE KEY uk_route_stop_labels_route_vertex_name (route_code, vertex_index, stop_name),
  INDEX idx_route_stop_labels_route (route_code),
  INDEX idx_route_stop_labels_name (stop_name)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS route_geometry_points (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  route_code VARCHAR(20) NOT NULL,
  segment_index SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  point_order INT UNSIGNED NOT NULL,
  longitude DECIMAL(10,7) NOT NULL,
  latitude DECIMAL(10,7) NOT NULL,
  UNIQUE KEY uk_route_geometry_points_route_segment_order (route_code, segment_index, point_order),
  INDEX idx_route_geometry_points_route (route_code),
  INDEX idx_route_geometry_points_order (route_code, segment_index, point_order)
) ENGINE=InnoDB;

